argv:
set -euo pipefail
# F15: Plan blob unchanged from parent, non-plan changes present
PLAN='docs/closure-plans/ACT-LEAMAS-FACTORY-CLOSURE-PROTOCOL-V2-PORTABLE-RUNNER-AUTHORITY01-CORRECTION04.json'
test "$(git rev-parse "HEAD^:$PLAN")" = "$(git rev-parse "HEAD:$PLAN")" || { echo "FAIL: plan blob changed" >&2; exit 1; }
# Implementation changes must be present (S6 must add real production files)
test -n "$(git diff-tree --no-commit-id --name-only -r HEAD | grep -v "^$PLAN\$")" || { echo "FAIL: no implementation changes" >&2; exit 1; }
# No closure artifacts in S6
test -z "$(git diff-tree --no-commit-id --name-only -r HEAD | grep -E '^(docs/closure-manifests/|docs/close-reports/|docs/closure-evidence/)')" || { echo "FAIL: closure artifacts in HEAD" >&2; exit 1; }
echo 'PASS: Plan blob immutability verified'
